<template>
  <v-dialog
    :model-value="modelValue"
    max-width="420"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="dialog-card">
      <div class="dialog-head">
        <div class="dialog-title">{{ text.title }}</div>
        <v-icon
          icon="mdi-close"
          size="18"
          @click="$emit('update:modelValue', false)"
        />
      </div>

      <template v-if="step === 1">
        <div class="field-label mb-2">{{ text.chartTypeLabel }}</div>
        <div class="type-grid mb-4">
          <div
            v-for="ct in chartTypes"
            :key="ct.value"
            class="type-card"
            :class="{ active: form.chartType === ct.value }"
            @click="form.chartType = ct.value"
          >
            <v-icon :icon="ct.icon" size="22" />
            <div>{{ ct.label }}</div>
          </div>
        </div>
        <div class="d-flex justify-end">
          <button class="btn-primary" @click="step = 2">{{ text.next }}</button>
        </div>
      </template>

      <template v-else>
        <!-- <v-text-field
          v-model="search"
          prepend-inner-icon="mdi-magnify"
          :placeholder="text.searchPlaceholder"
          variant="outlined"
          density="compact"
          hide-details
          class="mb-4"
        /> -->
        <div class="field-label">
          {{ isSingleAttr ? text.attributeLabel : text.xAxisLabel }}
        </div>
        <v-select
          v-model="form.xAttr"
          :items="filteredAttrs"
          variant="outlined"
          density="compact"
          hide-details
          class="mb-4"
        />
        <!-- <template v-if="!isSingleAttr">
          <div class="field-label">{{ text.yAxisLabel }}</div>
          <v-select
            v-model="form.yAttr"
            :items="yAttrOptions"
            variant="outlined"
            density="compact"
            hide-details
            class="mb-4"
          />
        </template> -->
        <div class="d-flex justify-space-between mt-2">
          <button class="btn-outline" @click="step = 1">{{ text.back }}</button>
          <button
            class="btn-primary"
            
            :disabled="!form.xAttr "
            @click="submit"
          >
            {{ text.submit }}
          </button>
        </div>
      </template>
    </div>
  </v-dialog>
</template>

<script>
import { ATTRIBUTES, CHART_TYPE_OPTIONS, ADD_CHART_DEFAULT_FORM } from "@/utils/dashboardData";
import { ADD_CHART_TEXT } from "@/utils/uiText";

export default {
  name: "AddChartDialog",
  props: { modelValue: { type: Boolean, default: false } },
  emits: ["update:modelValue", "add"],

  data() {
    return {
      text: ADD_CHART_TEXT,
      step: 1,
      search: "",
      attributes: ATTRIBUTES,
      form: { ...ADD_CHART_DEFAULT_FORM },
      chartTypes: CHART_TYPE_OPTIONS,
    };
  },

  computed: {
    isSingleAttr() {
      return this.form.chartType === "donut";
    },
    filteredAttrs() {
      const q = this.search.trim().toLowerCase();
      return q
        ? this.attributes.filter((a) => a.toLowerCase().includes(q))
        : this.attributes;
    },
    yAttrOptions() {
      return this.attributes.filter((a) => a !== this.form.xAttr);
    },
  },

  watch: {
    modelValue(v) {
      if (v) {
        this.step = 1;
        this.form = { ...ADD_CHART_DEFAULT_FORM };
      }
    },
  },

  methods: {
    submit() {
      this.$emit("add", { ...this.form });
      this.$emit("update:modelValue", false);
    },
  },
};
</script>

<style scoped>
.dialog-card {
  background: #fff;
  padding: 20px;
  border-radius: 10px;
}
.dialog-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}
.dialog-title {
  font-size: 15px;
  font-weight: 600;
  color: #0f62fe;
}
.field-label {
  font-size: 12px;
  color: #666;
  margin-bottom: 4px;
}
.type-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}
@media (max-width: 480px) {
  .dialog-card { padding: 14px; }
}
.type-card {
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 12px 6px;
  text-align: center;
  font-size: 12px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}
.type-card.active {
  border-color: #0f62fe;
  background: rgba(15, 98, 254, 0.06);
  color: #0f62fe;
}
.btn-primary {
  color: #fff;
  background: #0f62fe;
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.btn-primary:disabled {
  background: #bdbdbd;
  cursor: not-allowed;
}
.btn-outline {
  border: 1px solid #ddd;
  background: #fff;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  cursor: pointer;
}
</style>