<template>
  <Teleport to="body">
    <Transition name="toast">
      <div
        v-if="show"
        class="toast"
        :class="`toast--${type}`"
        role="alert"
        @mouseenter="pause"
        @mouseleave="start"
      >
        <span class="toast-icon">
          <v-icon :icon="meta.icon" size="18" />
        </span>

        <div class="toast-body">
          <div class="toast-title">{{ meta.title }}</div>
          <div class="toast-msg">{{ message }}</div>
        </div>

        <button class="toast-close" aria-label="Close" @click="hide">
          <v-icon icon="mdi-close" size="16" />
        </button>

        <span
          :key="tick"
          class="toast-progress"
          :class="{ paused }"
          :style="{ animationDuration: timeout + 'ms' }"
        />
      </div>
    </Transition>
  </Teleport>
</template>

<script>
import { toastBus } from "./toastBus";

const TYPES = {
  success: { title: "Success", icon: "mdi-check-circle" },
  error: { title: "Something went wrong", icon: "mdi-alert-circle" },
  warning: { title: "Warning", icon: "mdi-alert" },
  info: { title: "Info", icon: "mdi-information" },
};

export default {
  name: "AppToast",
  data() {
    return { show: false, message: "", type: "success", tick: 0, paused: false, timer: null };
  },
  computed: {
    meta() {
      return TYPES[this.type];
    },
    timeout() {
      return this.type === "error" ? 5000 : 3500;
    },
  },
  mounted() {
    toastBus.on((msg, type = "success") => {
      this.message = msg;
      this.type = TYPES[type] ? type : "success";
      this.tick++; // restarts the progress bar for back-to-back toasts
      this.show = true;
      this.start();
    });
  },
  beforeUnmount() {
    clearTimeout(this.timer);
  },
  methods: {
    start() {
      this.paused = false;
      clearTimeout(this.timer);
      this.timer = setTimeout(this.hide, this.timeout);
    },
    pause() {
      this.paused = true;
      clearTimeout(this.timer);
    },
    hide() {
      clearTimeout(this.timer);
      this.show = false;
    },
  },
};
</script>

<style scoped>
.toast {
  --accent: #24a148;
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 10000;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 360px;
  max-width: calc(100vw - 40px);
  padding: 14px 44px 16px 14px;
  box-sizing: border-box;
  background: #fff;
  color: #1a1a1a;
  border: 1px solid #e3e3e3;
  border-left: 4px solid var(--accent);
  border-radius: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
  overflow: hidden;
  font-family: inherit;
}
.toast--error { --accent: #da1e28; }
.toast--warning { --accent: #f1a100; }
.toast--info { --accent: #0f62fe; }

.toast-icon {
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, #fff);
}
.toast-body {
  flex: 1;
  min-width: 0;
}
.toast-title {
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
}
.toast-msg {
  margin-top: 2px;
  font-size: 13px;
  line-height: 18px;
  color: #555;
  word-break: break-word;
}
.toast-close {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #888;
  cursor: pointer;
}
.toast-close:hover {
  background: #f2f2f2;
  color: #222;
}

.toast-progress {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 3px;
  width: 100%;
  background: var(--accent);
  transform-origin: left;
  animation: toast-shrink linear forwards;
}
.toast-progress.paused {
  animation-play-state: paused;
}
@keyframes toast-shrink {
  from { transform: scaleX(1); }
  to { transform: scaleX(0); }
}

/* slide in from the right */
.toast-enter-active,
.toast-leave-active {
  transition: transform 0.25s ease, opacity 0.25s ease;
}
.toast-enter-from,
.toast-leave-to {
  transform: translateX(24px);
  opacity: 0;
}

@media (max-width: 480px) {
  .toast { top: 12px; right: 12px; left: 12px; width: auto; max-width: none; }
}
</style>