<template>
  <v-dialog persistent :model-value="modelValue" max-width="460" @update:model-value="$emit('update:modelValue', $event)">
    <div class="sc-card">
      <div class="sc-head">
        <div class="sc-title">Which project do you want to see?</div>
        <button class="sc-close" aria-label="Close" @click="$emit('update:modelValue', false)">
          <v-icon icon="mdi-close" size="18" />
        </button>
      </div>

      <div class="sc-body sc-options">
        <button class="sc-option" @click="$emit('pick', '3dx')">
          <v-icon icon="mdi-cube-outline" size="26" />
          <span>3DEXPERIENCE</span>
        </button>
        <button class="sc-option" :disabled="busy" @click="chooseExternal">
          <v-icon icon="mdi-open-in-new" size="26" />
          <span>{{ busy ? "Connecting…" : "External" }}</span>
        </button>
      </div>
      <div v-if="error" class="sc-error">{{ error }}</div>
    </div>
  </v-dialog>
</template>

<script>
import externalApi from "@/services/externalApi";

export default {
  props: { modelValue: Boolean },
  emits: ["update:modelValue", "pick"],
  data: () => ({ busy: false, error: "" }),
  watch: {
    modelValue(v) {
      if (v) this.error = "";
    },
  },
  methods: {
    async chooseExternal() {
      this.busy = true;
      this.error = "";
      try {
        await externalApi.ensureLogin(); // uses the widget preferences
        this.$emit("pick", "external");
      } catch (e) {
        this.error = e.message;
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<style scoped>
.sc-card { background: #fff; border-radius: 14px; overflow: hidden; box-shadow: 0 12px 40px rgba(0, 0, 0, 0.18); }
.sc-head { display: flex; align-items: center; justify-content: space-between; padding: 18px 20px 18px 24px; border-bottom: 1px solid #eee; }
.sc-title { font-size: 17px; font-weight: 700; color: #1a1a1a; }
.sc-close { width: 30px; height: 30px; border: 0; border-radius: 50%; background: transparent; color: #777; cursor: pointer; }
.sc-close:hover { background: #f0f2f5; }
.sc-body { padding: 22px 24px; }
.sc-options { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.sc-option { display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 24px 8px; border: 1px solid #ddd; border-radius: 10px; background: #fff; color: #333; font-size: 14px; font-weight: 600; cursor: pointer; transition: border-color 0.15s, background 0.15s; }
.sc-option:hover:not(:disabled) { border-color: #0f62fe; background: rgba(15, 98, 254, 0.06); color: #0f62fe; }
.sc-option:disabled { opacity: 0.6; cursor: wait; }
.sc-error { margin: 0 24px 20px; padding: 10px 12px; border-radius: 8px; background: #fff1f1; color: #da1e28; font-size: 13px; }
</style>