const DAY = 86400000;
const ts = (v) => {
  const t = v ? new Date(v).getTime() : NaN;
  return isNaN(t) ? null : t;
};
function inRange(v, from, to) {
  if (!from && !to) return true;
  const t = ts(v);
  if (t == null) return false;
  if (from && t < new Date(from + "T00:00:00").getTime()) return false;
  if (to && t > new Date(to + "T23:59:59.999").getTime()) return false;
  return true;
}

export function applyFilters(rows, f) {
  const q = f.search.trim().toLowerCase();
  return rows.filter(
    (r) =>
      (!f.type.length || f.type.includes(r.type)) &&
      (!f.status.length || f.status.includes(r.status)) &&
      (!f.role.length || f.role.some((x) => r.roles.includes(x))) &&
      (!q || `${r.title} ${r.name}`.toLowerCase().includes(q)) &&
      inRange(r.created, f.createdFrom, f.createdTo) &&
      inRange(r.modified, f.modifiedFrom, f.modifiedTo),
  );
}

const countBy = (rows, key) => {
  const m = new Map();
  rows.forEach((r) => m.set(r[key] || "–", (m.get(r[key] || "–") || 0) + 1));
  return [...m].sort((a, b) => b[1] - a[1]);
};

export function summarize(rows) {
  const has = (role) => rows.filter((r) => r.roles.includes(role)).length;
  return {
    total: rows.length,
    owner: has("owner"),
    created: has("created"),
    byType: countBy(rows, "type"),
    byStatus: countBy(rows, "status"),
  };
}

const bucket = (t, g) => {
  const d = new Date(t);
  d.setHours(0, 0, 0, 0);
  if (g === "week") d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
  if (g === "month") d.setDate(1);
  return d.getTime();
};
const nextBucket = (t, g) => {
  const d = new Date(t);
  if (g === "month") d.setMonth(d.getMonth() + 1);
  else d.setDate(d.getDate() + (g === "week" ? 7 : 1));
  return d.getTime();
};

// my items per day / week / month (by created date), one series per role: { labels, owner, created }
export function timeline(rows) {
  const ev = [];
  rows.forEach((r) => {
    const t = ts(r.created);
    if (t != null) r.roles.forEach((role) => ev.push([role, t]));
  });
  if (!ev.length) return { labels: [], keys: [], g: "day", owner: [], created: [] };

  const all = ev.map((e) => e[1]);
  const lo = Math.min(...all);
  const hi = Math.max(...all);
  const span = (hi - lo) / DAY;
  const g = span <= 45 ? "day" : span <= 200 ? "week" : "month";

  const keys = [];
  for (let k = bucket(lo, g); k <= hi; k = nextBucket(k, g)) keys.push(k);
  const at = new Map(keys.map((k, i) => [k, i]));
  const out = { owner: keys.map(() => 0), created: keys.map(() => 0) };
  ev.forEach(([role, t]) => {
    const i = at.get(bucket(t, g));
    if (i != null && out[role]) out[role][i]++;
  });
  const fmt = g === "month" ? { month: "short", year: "2-digit" } : { day: "numeric", month: "short" };
  return { labels: keys.map((k) => new Date(k).toLocaleDateString(undefined, fmt)), keys, g, ...out };
}

// is the item's created date inside the chart bucket starting at `key`?
export const inBucket = (row, key, g) => {
  const t = ts(row.created);
  return t != null && bucket(t, g) === key;
};

// how long ago items were last modified: [[label, count], ...]
export function ageBuckets(rows, now = Date.now()) {
  const bands = [["≤ 7 days", 7], ["8–30 days", 30], ["31–90 days", 90], ["> 90 days", Infinity]];
  const out = bands.map(([label]) => [label, 0]);
  rows.forEach((r) => {
    const t = ts(r.modified);
    if (t == null) return;
    const age = (now - t) / DAY;
    out[bands.findIndex(([, max]) => age <= max)][1]++;
  });
  return out;
}