<template>
  <div class="drill-panel">
    <div class="drill-head">
      <div class="drill-title">{{ text.title }}</div>
      <div class="drill-chip">
        {{ drill.filterLabel }}
        <v-icon icon="mdi-close" size="14" title="Remove filter" @click="$emit('close')" />
      </div>
      <v-icon icon="mdi-close" size="18" title="Close" class="drill-close" @click="$emit('close')" />
    </div>

    <div v-if="drill.loading" class="drill-loading">
      <v-progress-circular indeterminate color="#0F62FE" size="40" />
      <div class="mt-3" style="font-weight: 600">{{ text.loading }}</div>
      <div class="text-medium-emphasis" style="font-size: 12px">{{ text.loadingSub }}</div>
    </div>

    <template v-else>
      <div class="drill-count">{{ (drill.total || 0).toLocaleString() }} {{ text.itemsSuffix }}</div>
      <div class="drill-table-wrap">
        <table class="drill-table">
          <thead>
            <tr>
              <th v-for="c in columns" :key="c.key">
                <div class="th-label">{{ c.label }}</div>
                <input
                  v-model="filters[c.key]"
                  :list="'dl-' + c.key"
                  :placeholder="text.filterPlaceholder"
                  autocomplete="off"
                />
                <datalist :id="'dl-' + c.key">
                  <option v-for="v in columnValues(c.key)" :key="v" :value="v" />
                </datalist>
              </th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="(r, ri) in filteredItems" :key="ri">
              
              <td v-for="c in columns" :key="c.key">
                {{ c.formatter ? c.formatter(r[c.key]) : r[c.key] }}
              </td>
              
            </tr>
            <tr v-if="!filteredItems.length">
              <td :colspan="columns.length" class="drill-empty">{{ text.empty }}</td>
            </tr>
          </tbody>
        </table>
      </div>
      <div class="pager">
        <v-icon icon="mdi-chevron-left" size="16" title="Previous page" @click="$emit('page', drill.page - 1)" />
        <span>{{ text.pagePrefix }} {{ drill.page }} {{ text.pageJoiner }} {{ totalPages }}</span>
        <v-icon icon="mdi-chevron-right" size="16" title="Next page" @click="$emit('page', drill.page + 1)" />
      </div>
    </template>
  </div>
</template>

<script>
import { DRILLDOWN_PAGE_SIZE, DRILLDOWN_COLUMNS, DRILLDOWN_COLUMNS2, DrillDown_Engineering, EXTERNAL_PROJECT_COLUMNS } from "@/utils/dashboardData";
import { DRILLDOWN_TEXT } from "@/utils/uiText";
import { useDashboardStore } from "@/store/dashboardStore";
export default {
  name: "DrillDownPanel",
  props: { drill: { type: Object, required: true } },
  emits: ["close", "page"],
    setup() {
    return { store: useDashboardStore() };
  },
  data() {
    return {
      text: DRILLDOWN_TEXT,
      filters: Object.fromEntries(DRILLDOWN_COLUMNS.map((c) => [c.key, ""])),
    };
  },
  computed: {
    columns() {
      if (this.store.source === "external") return EXTERNAL_PROJECT_COLUMNS;
      // return this.store.type != "Issue" ? DRILLDOWN_COLUMNS : DRILLDOWN_COLUMNS2;
      return this.store.type == "Project"  || this.store.type == "Program"  || this.store.type == "Document"  || this.store.type == "Task"? DRILLDOWN_COLUMNS : this.store.type == "Engineering" ? DrillDown_Engineering : DRILLDOWN_COLUMNS2;
    },
    totalPages() {
      return Math.max(1, Math.ceil((this.drill.total || 0) / DRILLDOWN_PAGE_SIZE));
    },
    filteredItems() {
      return (this.drill.items || []).filter((r) =>
        this.columns.every((c) =>
          String(r[c.key] || "").toLowerCase().includes((this.filters[c.key] || "").toLowerCase())
        )
      );
    },
  },
  methods: {
    columnValues(key) {
      return [...new Set((this.drill.items || []).map((r) => r[key]).filter(Boolean))];
    },
  },
};
</script>

<style scoped>
.drill-panel {
  width: 800px;
  max-width: 100%;
  height: calc(100vh - 70px);
  flex-shrink: 0;
  background: #fff;
  border: 1px solid #eee;
  border-radius: 10px;
  padding: 16px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.drill-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
  flex-shrink: 0;
}
.drill-close {
  margin-left: auto;
}
.drill-head .v-icon,
.drill-chip .v-icon,
.pager .v-icon {
  cursor: pointer;
}
.drill-title {
  font-size: 13px;
  font-weight: 600;
  color: #0f62fe;
  flex-shrink: 0;
}
.drill-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #e8f0fe;
  color: #0f62fe;
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 6px;
  flex-shrink: 0;
}
.drill-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 10px;
  text-align: center;
}
.drill-count {
  font-size: 12px;
  color: #666;
  margin-bottom: 8px;
  flex-shrink: 0;
}
.drill-table-wrap {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: auto;
}
.drill-table thead th {
  position: sticky;
  top: 0;
  background: #fff;
  z-index: 2;
}
.drill-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  min-width: 480px;
}
.drill-table th {
  text-align: left;
  color: #888;
  font-weight: 600;
  padding: 6px 4px;
  border-bottom: 1px solid #eee;
  white-space: nowrap;
  background: #fff;
  position: sticky;
  top: 0;
  vertical-align: top;
}
.th-label {
  margin-bottom: 4px;
}
.drill-table th input {
  width: 100%;
  box-sizing: border-box;
  font-size: 11px;
  padding: 4px 6px;
  border: 1px solid #ddd;
  border-radius: 4px;
  font-weight: normal;
  color: #333;
}
.drill-table td {
  padding: 6px 4px;
  border-bottom: 1px solid #f5f5f5;
  color: #333;
  white-space: nowrap;
}
.drill-empty {
  text-align: center;
  color: #999;
  padding: 16px 4px;
}
.pager {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-size: 12px;
  margin-top: 10px;
  color: #666;
  flex-shrink: 0;
}
.open-link {
  margin-top: 14px;
  font-size: 12px;
  color: #0f62fe;
  cursor: pointer;
  flex-shrink: 0;
}
@media (max-width: 900px) {
  .drill-panel {
    position: fixed;
    inset: 0;
    width: 100%;
    max-height: 100%;
    z-index: 20;
    border-radius: 0;
  }
}
.drill-table-wrap::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.drill-table-wrap::-webkit-scrollbar-thumb {
  background: #c7c7c7;
  border-radius: 4px;
}
.drill-table-wrap::-webkit-scrollbar-thumb:hover {
  background: #999;
}
</style>