.filter-pill { font-size: 13px; color: #0f62fe; cursor: pointer; }
.fp-card { width: 320px; max-width: 90vw; max-height: 70vh; overflow-y: auto; background: #fff; padding: 16px; }
.fp-head { display: flex; justify-content: flex-end; margin-bottom: 4px; }
.fp-head .v-icon { cursor: pointer; }
.fp-group { margin-bottom: 16px; }
.fp-label { font-size: 13px; font-weight: 700; color: #1a1a1a; margin-bottom: 8px; }
.fp-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.fp-chip { border: 1px solid #ddd; border-radius: 20px; padding: 5px 12px; font-size: 12px; cursor: pointer; color: #444; }
.fp-chip.active { border-color: #0f62fe; color: #0f62fe; background: rgba(15, 98, 254, 0.08); font-weight: 600; }
.fp-date-row { display: flex; align-items: center; gap: 8px; }
.fp-date-input { flex: 1; border: 1px solid #ddd; border-radius: 8px; padding: 7px 8px; font-size: 12px; color: #333; }
.fp-date-sep { font-size: 12px; color: #888; }
.fp-btn { width: 100%; margin-top: 4px; background: #0f62fe; color: #fff; border: none; border-radius: 8px; padding: 10px; font-size: 13px; font-weight: 600; cursor: pointer; }
</style>