<template>
  <v-dialog
    :model-value="modelValue"
    max-width="420"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="vs-card">
      <div class="vs-head">
        <span>{{ text.title }}</span>
        <v-icon icon="mdi-close" size="18" @click="close" />
      </div>

      <div class="vs-tabs">
        <div
          v-for="t in tabs"
          :key="t"
          class="vs-tab"
          :class="{ active: tab === t }"
          @click="tab = t"
        >
          {{ t }}
        </div>
      </div>

      <template v-if="tab === 'Layout'">
        <div class="field-label">{{ text.layoutLabel }}</div>
        <div class="cols-grid">
          <div
            v-for="n in columnChoices"
            :key="n"
            class="cols-card"
            :class="{ active: form.columns === n }"
            @click="form.columns = n"
          >
            <div class="cols-preview"><span v-for="i in n" :key="i" /></div>
            <div>{{ n }} Columns</div>
          </div>
        </div>

        <div class="toggle-row">
          <span>{{ text.showKpis }}</span
          ><v-switch
            v-model="form.showKpis"
            color="#0F62FE"
            hide-details
            density="compact"
          />
        </div>
        <div class="toggle-row">
          <span>{{ text.showFilterBar }}</span
          ><v-switch
            v-model="form.showFilterBar"
            color="#0F62FE"
            hide-details
            density="compact"
          />
        </div>
        <div class="toggle-row">
          <span>{{ text.compactMode }}</span
          ><v-switch
            v-model="form.compact"
            color="#0F62FE"
            hide-details
            density="compact"
          />
        </div>
      </template>
      <template v-else>
        <div
          class="text-medium-emphasis"
          style="font-size: 13px; padding: 20px 0"
        >
          {{ text.comingSoon }}
        </div>
      </template>

      <div class="vs-actions">
        <button class="btn-outline" @click="reset">{{ text.reset }}</button>
        <button class="btn-primary" @click="apply">{{ text.apply }}</button>
      </div>
    </div>
  </v-dialog>
</template>

<script>
import { DEFAULT_VIEW_SETTINGS, VIEW_SETTINGS_TABS, LAYOUT_COLUMN_CHOICES } from "@/utils/dashboardData";
import { VIEW_SETTINGS_TEXT } from "@/utils/uiText";

export default {
  name: "ViewSettingsDialog",
  props: {
    modelValue: { type: Boolean, default: false },
    settings: { type: Object, default: () => ({ ...DEFAULT_VIEW_SETTINGS }) },
  },
  emits: ["update:modelValue", "apply"],

  data() {
    return {
      text: VIEW_SETTINGS_TEXT,
      tab: "Layout",
      tabs: VIEW_SETTINGS_TABS,
      columnChoices: LAYOUT_COLUMN_CHOICES,
      form: { ...DEFAULT_VIEW_SETTINGS, ...this.settings },
    };
  },

  watch: {
    modelValue(v) {
      if (v) this.form = { ...DEFAULT_VIEW_SETTINGS, ...this.settings };
    },
  },

  methods: {
    close() {
      this.$emit("update:modelValue", false);
    },
    reset() {
      this.form = { ...DEFAULT_VIEW_SETTINGS };
    },
    apply() {
      this.$emit("apply", { ...this.form });
      this.close();
    },
  },
};
</script>

<style scoped>
.vs-card {
  background: #fff;
  border-radius: 10px;
  padding: 20px;
}
.vs-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 14px;
}
.vs-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}
.vs-tab {
  font-size: 12px;
  padding: 5px 10px;
  border-radius: 6px;
  color: #666;
  cursor: pointer;
}
.vs-tab.active {
  background: #e8f0fe;
  color: #0f62fe;
  font-weight: 600;
}
.field-label {
  font-size: 12px;
  color: #666;
  margin-bottom: 8px;
}
.cols-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 16px;
}
.cols-card {
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 10px 6px;
  text-align: center;
  font-size: 12px;
  cursor: pointer;
}
.cols-card.active {
  border-color: #0f62fe;
  background: rgba(15, 98, 254, 0.06);
  color: #0f62fe;
}
.cols-preview {
  display: flex;
  gap: 3px;
  justify-content: center;
  margin-bottom: 6px;
  height: 24px;
  align-items: flex-end;
}
.cols-preview span {
  flex: 1;
  max-width: 16px;
  height: 100%;
  background: #ccc;
  border-radius: 2px;
}
.cols-card.active .cols-preview span {
  background: #0f62fe;
}
.toggle-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: #444;
  margin-bottom: 8px;
}
.vs-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 16px;
}
.btn-primary {
  color: #fff;
  background: #0f62fe;
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.btn-outline {
  border: 1px solid #ddd;
  background: #fff;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  cursor: pointer;
}
@media (max-width: 480px) {
  .cols-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
</style>